def fit4pl(c,y):
    # parameters log10(EC50), log(h), bottom; upper asymptote fixed 1
    def resid(p):
        e=10**p[0]; h=10**p[1]; b=p[2]
        pred=b+(1-b)/(1+(np.asarray(c)/e)**h)
